const asText = b => (b == null ? '' : typeof b === 'string' ? b : (b.type === 'Buffer' && Array.isArray(b.data)) ? Buffer.from(b.data).toString('utf8') : JSON.stringify(b));

// UNGM needs a session cookie and an anti-forgery token, fetched once per run.
let ungm = null;
async function ungmSession(origin) {
  if (ungm) return ungm;
  const r = await http({ method: 'GET', url: origin + '/Public/Notice', headers: BASE_HEADERS, returnFullResponse: true, timeout: TIMEOUT_MS, encoding: 'text', json: false });
  const html = asText(r.body);
  const m = html.match(/name="__RequestVerificationToken"[^>]*value="([^"]+)"/) || html.match(/value="([^"]+)"[^>]*name="__RequestVerificationToken"/);
  let sc = (r.headers || {})['set-cookie'] || [];
  if (!Array.isArray(sc)) sc = [sc];
  ungm = { token: m ? m[1] : '', cookie: sc.map(c => String(c).split(';')[0]).join('; ') };
  if (!ungm.token) throw new Error('UNGM token not found');
  return ungm;
}

async function fetchOne(src) {
  const req = { method: src.method, url: src.url, headers: Object.assign({}, BASE_HEADERS), timeout: TIMEOUT_MS, json: false, encoding: 'text', returnFullResponse: true };
  if (src.parser === 'ungm') {
    const pu = parseUrl(src.url); const origin = pu.protocol + '//' + pu.host;
    const s = await ungmSession(origin);
    let extra = {}; try { extra = src.body ? JSON.parse(src.body) : {}; } catch (e) {}
    req.method = 'POST';
    req.body = JSON.stringify(Object.assign({
      PageIndex: 0, PageSize: 15, Title: '', Description: '', Reference: '', PublishedFrom: '', PublishedTo: '',
      DeadlineFrom: ddMonYYYY(cfg.today), DeadlineTo: '', Countries: [], Agencies: [], UNSPSCs: [], NoticeTypes: [],
      SortField: 'Deadline', SortAscending: true, isPicker: false, IsSustainable: false, IsActive: true,
      NoticeDisplayType: null, NoticeSearchTotalLabelId: 'noticeSearchTotal', TypeOfCompetitions: []
    }, extra));
    Object.assign(req.headers, { 'Content-Type': 'application/json', 'X-Requested-With': 'XMLHttpRequest', 'RequestVerificationToken': s.token, 'Cookie': s.cookie, 'Accept': 'text/html, */*' });
  } else if (src.parser === 'sedia') {
    // EU Funding & Tenders search API: multipart/form-data whose parts are JSON "files".
    const boundary = '----remedi' + fnv(src.url + Date.now());
    const parts = [['query', src.body || '{"bool":{"must":[{"terms":{"type":["1","2","8"]}},{"terms":{"status":["31094501","31094502"]}}]}}'], ['languages', '["en"]'], ['sort', '{"field":"sortStatus","order":"ASC"}']];
    req.method = 'POST';
    req.body = parts.map(([n, v]) => `--${boundary}\r\nContent-Disposition: form-data; name="${n}"; filename="blob"\r\nContent-Type: application/json\r\n\r\n${v}\r\n`).join('') + `--${boundary}--\r\n`; // a string, so n8n sends it untouched
    Object.assign(req.headers, { 'Content-Type': `multipart/form-data; boundary=${boundary}`, 'Accept': 'application/json' });
  } else if (src.method === 'POST') {
    req.body = src.body || '{}';
    Object.assign(req.headers, { 'Content-Type': 'application/json', 'Accept': 'application/json' });
  }
  const r = await http(req);
  return { status: r.statusCode, data: asText(r.body).slice(0, MAX_CHARS) };
}

