const queues = Object.values(byHost);
const results = [];

async function worker() {
  while (queues.length) {
    const q = queues.shift();
    for (let k = 0; k < q.length; k++) {
      const src = q[k];
      if (Date.now() - started > BUDGET_MS) { results.push({ src, error: 'skipped: run time budget used up' }); continue; }
      try { results.push(Object.assign({ src }, await fetchOne(src))); }
      catch (e) {
        const code = e.httpCode || (e.response && e.response.status) || '';
        results.push({ src, error: cut(`${code ? code + ' ' : ''}${e.message || e}`, 200) });
      }
      if (k < q.length - 1) await sleep(src.parser === 'ungm' ? 3000 : GAP_MS);
    }
  }
}
await Promise.all(Array.from({ length: Math.min(HOSTS_IN_PARALLEL, queues.length) }, worker));
if (!results.length) return [{ json: { src: { name: 'none', parser: 'none' }, error: 'no active sources' } }];
return results.map(r => ({ json: r }));

// ---------- shared helpers (same block in every Code node) ----------
const CATEGORIES = ['CSR - India', 'Govt Tender - India', 'Intl Govt Tender (partner-led)', 'International Grant', 'Innovation Grant - India'];
const MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, sept: 9, oct: 10, nov: 11, dec: 12,
  january: 1, february: 2, march: 3, april: 4, june: 6, july: 7, august: 8, september: 9, october: 10, november: 11, december: 12 };

function fnv(str) {
  let h = 0x811c9dc5;
  const s = String(str || '');
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  return ('0000000' + (h >>> 0).toString(16)).slice(-8);
}

function decodeEntities(s) {
  return String(s || '')
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"').replace(/&#0?39;|&apos;|&rsquo;|&lsquo;/gi, "'").replace(/&ldquo;|&rdquo;/gi, '"')
    .replace(/&ndash;/gi, '-').replace(/&mdash;/gi, '-').replace(/&hellip;/gi, '...')
    .replace(/&#(\d+);/g, (m, d) => String.fromCharCode(+d))
    .replace(/&#x([0-9a-f]+);/gi, (m, h) => String.fromCharCode(parseInt(h, 16)));
}

function clean(s) { return decodeEntities(String(s || '').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim(); }

// n8n's Code sandbox has no URL global, so URLs are handled with small string helpers.
function parseUrl(u) {
  const m = String(u || '').trim().match(/^([a-z][a-z0-9+.\-]*:)\/\/([^\/?#]*)([^?#]*)(\?[^#]*)?(#.*)?$/i);
  return m ? { protocol: m[1].toLowerCase(), host: m[2].toLowerCase(), path: m[3] || '/', search: m[4] || '', hash: m[5] || '' } : null;
}
function normPath(p) {
  const q = p.search(/[?#]/); const tail = q >= 0 ? p.slice(q) : ''; const path = q >= 0 ? p.slice(0, q) : p;
  const out = [];
  for (const seg of path.split('/')) { if (seg === '..') { if (out.length > 1) out.pop(); } else if (seg !== '.') out.push(seg); }
  let r = out.join('/'); if (!r.startsWith('/')) r = '/' + r;
  return r + tail;
}
function absUrl(href, base) {
  if (!href) return '';
  href = decodeEntities(href).trim();
  if (/^(javascript:|mailto:|tel:|#)/i.test(href)) return '';
  if (/^[a-z][a-z0-9+.\-]*:/i.test(href)) return href;
  const b = parseUrl(base); if (!b) return '';
  if (href.startsWith('//')) return b.protocol + href;
  const origin = b.protocol + '//' + b.host;
  if (href.startsWith('/')) return origin + normPath(href);
  if (href.startsWith('?')) return origin + b.path + href;
  return origin + normPath(b.path.replace(/[^\/]*$/, '') + href);
}
function canonicalUrl(u) {
  const p = parseUrl(u);
  if (!p) return String(u || '').toLowerCase().trim();
  const qs = p.search.replace(/^\?/, '').split('&').filter(kv => kv && !/^(utm_[a-z]+|fbclid|gclid)=/i.test(kv)).join('&');
  return (p.host.replace(/^www\./, '') + p.path.replace(/\/+$/, '') + (qs ? '?' + qs : '')).toLowerCase();
}

function pad(n) { return String(n).padStart(2, '0'); }
function isoFromParts(y, m, d) {
  y = +y; m = +m; d = +d;
  if (y < 100) y += 2000;
  if (!(y > 1990 && y < 2100 && m >= 1 && m <= 12 && d >= 1 && d <= 31)) return '';
  return `${y}-${pad(m)}-${pad(d)}`;
}

// Parse the many date styles these sources use. order: 'dmy' (India/UN default) or 'mdy' (US sources).
function toISODate(input, order) {
  if (!input) return '';
  let s = clean(String(input)).replace(/(\d)(st|nd|rd|th)\b/gi, '$1');
  let m;
  if ((m = s.match(/\b(\d{4})-(\d{1,2})-(\d{1,2})/))) return isoFromParts(m[1], m[2], m[3]);
  if ((m = s.match(/\b(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})\b/))) {
    return order === 'mdy' ? isoFromParts(m[3], m[1], m[2]) : isoFromParts(m[3], m[2], m[1]);
  }
  if ((m = s.match(/\b(\d{1,2})[\s\-.\/]+([A-Za-z]{3,9})\.?,?[\s\-.\/]+(\d{2,4})\b/))) {
    const mo = MONTHS[m[2].toLowerCase()];
    if (mo) return isoFromParts(m[3], mo, m[1]);
  }
  if ((m = s.match(/\b([A-Za-z]{3,9})\.?\s+(\d{1,2}),?\s+(\d{4})\b/))) {
    const mo = MONTHS[m[1].toLowerCase()];
    if (mo) return isoFromParts(m[3], mo, m[2]);
  }
  const t = Date.parse(s);
  if (!isNaN(t)) { const d = new Date(t); return isoFromParts(d.getUTCFullYear(), d.getUTCMonth() + 1, d.getUTCDate()); }
  return '';
}

// Find a deadline mentioned inside free text ("Deadline: 10 Oct. 2026", "Last date of submission 31-10-2026").
function deadlineFromText(text, order) {
  const s = clean(text);
  const re = /(deadline|last date(?: of submission)?|closing date|closes(?: on)?|apply by|due date|submission date|bid end date|last submission date)\s*(?:is|:|-|–)?\s*([^|;]{4,40})/gi;
  let m;
  while ((m = re.exec(s))) { const d = toISODate(m[2], order); if (d) return d; }
  return '';
}

function todayISO() {
  // Asia/Kolkata date
  const now = new Date(Date.now() + 5.5 * 3600 * 1000);
  return isoFromParts(now.getUTCFullYear(), now.getUTCMonth() + 1, now.getUTCDate());
}

function matchCount(text, keywords) {
  const s = ' ' + String(text || '').toLowerCase() + ' ';
  let n = 0;
  for (const k of keywords || []) { if (k && s.includes(String(k).toLowerCase())) n++; }
  return n;
}

function truthy(v) { return v === true || /^(true|yes|y|1|on)$/i.test(String(v == null ? '' : v).trim()); }

function makeUid(o) {
  if (o.ref_no && String(o.ref_no).replace(/\W/g, '').length >= 6) return 'R' + fnv(String(o.ref_no).toLowerCase().replace(/\W/g, ''));
  if (o.url && !o.url_is_listing) return 'U' + fnv(canonicalUrl(o.url));
  return 'T' + fnv(titleKey(o.title) + '|' + String(o.funder_buyer || '').toLowerCase());
}

function titleKey(t) { return String(t || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().slice(0, 90); }

// Pull the first JSON object/array out of a model reply (handles ```json fences and <json> tags).
function extractJson(text) {
  if (!text) return null;
  let t = String(text);
  const tag = t.match(/<json>([\s\S]*?)<\/json>/i);
  if (tag) t = tag[1];
  t = t.replace(/```(?:json)?/gi, '');
  const starts = [t.indexOf('{'), t.indexOf('[')].filter(i => i >= 0);
  if (!starts.length) return null;
  const start = Math.min(...starts);
  const end = Math.max(t.lastIndexOf('}'), t.lastIndexOf(']'));
  if (end <= start) return null;
  try { return JSON.parse(t.slice(start, end + 1)); } catch (e) { return null; }
}

function claudeText(resp) {
  if (!resp || !Array.isArray(resp.content)) return '';
  return resp.content.filter(b => b.type === 'text').map(b => b.text).join('');
}

function cut(s, n) { s = String(s || ''); return s.length > n ? s.slice(0, n - 1) + '…' : s; }
// ---------- end shared helpers ----------

// Turns each fetched response into opportunities (structured sources) or page text for Claude (HTML sources).
const cfg = $('Config').first().json;
const today = cfg.today;
const kw = cfg.keywords || [];
const store = $getWorkflowStaticData('global');
store.pageHashes = store.pageHashes || {};
const out = [];

function opp(src, o) {
  const title = clean(o.title);
  if (!title) return;
  const text = `${title} ${o.summary || ''}`;
  if (src.prefilter && matchCount(text, kw) === 0) return;
  out.push({ json: Object.assign({
    kind: 'opp', category: src.category, source: src.name, funder_buyer: '', country: '', deadline: '', amount: '',
    url: '', ref_no: '', summary: '', published: ''
  }, o, { title, summary: cut(clean(o.summary), 700) }) });
}

// HTML -> readable lines; links kept as "text [url]" so Claude can return the right link per item.
function htmlToLines(html, base) {
  let s = String(html || '');
  s = s.replace(/<(script|style|noscript|svg|head|iframe)[\s\S]*?<\/\1>/gi, ' ').replace(/<!--[\s\S]*?-->/g, ' ');
  s = s.replace(/<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi, (m, href, txt) => {
    const u = absUrl(href, base); const t = clean(txt);
    return t ? (u ? ` ${t} [${u}] ` : ` ${t} `) : '';
  });
  s = s.replace(/<\/(td|th)>/gi, ' | ').replace(/<(br|\/p|\/div|\/li|\/tr|\/h[1-6]|\/dt|\/dd|\/article|\/section)\b[^>]*>/gi, '\n');
  s = decodeEntities(s.replace(/<[^>]+>/g, ' '));
  return s.split('\n').map(l => l.replace(/[ \t]+/g, ' ').replace(/(\s*\|\s*)+$/, '').trim()).filter(l => l.length > 2);
}

function keepRelevant(lines) {
  const keep = new Set();
  lines.forEach((l, i) => { if (matchCount(l, kw) > 0) { keep.add(i - 1); keep.add(i); keep.add(i + 1); keep.add(i + 2); } });
  return lines.filter((l, i) => keep.has(i));
}

const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const res = items[i].json || {};
  const src = res.src || { name: 'unknown', parser: 'none' };
  if (src.parser === 'none') continue;
  if (res.error) { out.push({ json: { kind: 'error', source: src.name, error: String(res.error) } }); continue; }
  const raw = String(res.data || '');
  let data = null;
  const asJson = () => { if (data === null) { try { data = JSON.parse(raw); } catch (e) { data = {}; } } return data; };
  const before = out.length;
  try {
    switch (src.parser) {
      case 'rss': {
        const blocks = raw.match(/<item\b[\s\S]*?<\/item>|<entry\b[\s\S]*?<\/entry>/gi) || [];
        for (const b of blocks.slice(0, 60)) {
          const get = (tag) => { const m = b.match(new RegExp(`<${tag}\\b[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i')); return m ? decodeEntities(m[1]).trim() : ''; };
          let link = get('link'); if (!link) { const m = b.match(/<link[^>]*href=["']([^"']+)["']/i); link = m ? m[1] : ''; }
          const desc = get('content:encoded') || get('description') || get('summary') || get('content');
          const pub = get('pubDate') || get('published') || get('updated') || get('dc:date');
          opp(src, { title: get('title'), url: link.trim(), summary: desc, published: toISODate(pub), deadline: deadlineFromText(desc) });
        }
        break;
      }
      case 'grantsgov': {
        for (const h of (asJson().data && asJson().data.oppHits) || []) {
          opp(src, { title: h.title, funder_buyer: h.agency || h.agencyCode, country: 'Global / US-funded', deadline: toISODate(h.closeDate, 'mdy'),
            ref_no: h.number, url: `https://www.grants.gov/search-results-detail/${h.id}`, published: toISODate(h.openDate, 'mdy'),
            summary: `Status: ${h.oppStatus || ''}. ${h.docType === 'forecast' ? 'Forecast (not yet open). ' : ''}CFDA: ${(h.cfdaList || []).join(', ')}` });
        }
        break;
      }
      case 'worldbank': {
        const j = asJson();
        let rows = j.procnotices || j.documents || [];
        if (!Array.isArray(rows)) rows = Object.values(rows);
        for (const r of rows) {
          if (!r || typeof r !== 'object') continue;
          const type = String(r.notice_type || '');
          if (/award/i.test(type)) continue;
          const dl = toISODate(r.submission_deadline_date);
          if (!dl) continue;
          opp(src, { title: r.bid_description || r.project_name, funder_buyer: `World Bank project: ${r.project_name || r.project_id || ''}`,
            country: r.project_ctry_name || '', deadline: dl, ref_no: r.bid_reference_no || r.id,
            url: `https://projects.worldbank.org/en/projects-operations/procurement-detail/${r.id}`, published: toISODate(r.noticedate),
            summary: `${type}. ${r.procurement_group || ''} ${clean(r.notice_text).slice(0, 500)}` });
        }
        break;
      }
      case 'ted': {
        const pick = (v) => { if (!v) return ''; if (Array.isArray(v)) return pick(v[0]); if (typeof v === 'object') return pick(v.eng || v.ENG || Object.values(v)[0]); return String(v); };
        for (const n of asJson().notices || []) {
          const pn = n['publication-number'];
          opp(src, { title: pick(n['notice-title']), funder_buyer: pick(n['buyer-name']), country: [].concat(n['buyer-country'] || []).join(', '),
            deadline: toISODate(pick(n['deadline-receipt-tender-date-lot'])), ref_no: pn, published: toISODate(pick(n['publication-date'])),
            url: `https://ted.europa.eu/en/notice/-/detail/${pn}`, summary: `EU TED notice ${pick(n['notice-type'])}` });
        }
        break;
      }
      case 'sedia': {
        const seen = new Set();
        for (const r of asJson().results || []) {
          const md = r.metadata || {};
          const id = (md.identifier || [])[0] || (md.callIdentifier || [])[0];
          if (!id || seen.has(id)) continue; seen.add(id);
          const dls = (md.deadlineDate || []).map(d => toISODate(d)).filter(d => d && d >= today).sort();
          const status = (md.status || [])[0];
          if (!dls.length) continue;
          opp(src, { title: (md.title || [])[0] || r.summary || id, funder_buyer: 'European Commission (Funding & Tenders portal)', country: 'EU consortium',
            deadline: dls[0], ref_no: id, summary: `${status === '31094501' ? 'Forthcoming' : 'Open'} call. ${clean(r.summary || r.content || '').slice(0, 400)}`,
            url: `https://ec.europa.eu/info/funding-tenders/opportunities/portal/screen/opportunities/topic-details/${id}` });
        }
        break;
      }
      case 'wpjson': {
        const arr = Array.isArray(asJson()) ? asJson() : [];
        for (const p of arr) {
          const t = p.title && (p.title.rendered || p.title);
          const ex = (p.excerpt && p.excerpt.rendered) || (p.content && p.content.rendered) || '';
          opp(src, { title: t, url: p.link, published: toISODate(p.modified || p.date), summary: ex, deadline: deadlineFromText(ex) });
        }
        break;
      }
      case 'ungm': {
        const rows = raw.split(/data-noticeid="/).slice(1);
        const fallback = [];
        for (const chunk of rows) {
          const id = chunk.match(/^(\d+)/);
          const cells = chunk.split(/class="[^"]*\btableCell\b[^"]*"/).slice(1).map(c => clean(('<x ' + c).replace(/<[^>]*$/, '')));
          const url = id ? `https://www.ungm.org/Public/Notice/${id[1]}` : '';
          // Cell order: [save], title, deadline, published, agency, notice type, reference, beneficiary country
          const d = cells.findIndex((c, k) => k > 0 && toISODate(c));
          if (d >= 1 && cells.length >= d + 5) {
            opp(src, { title: cells[d - 1], deadline: toISODate(cells[d]), published: toISODate(cells[d + 1]), funder_buyer: ('UN ' + (cells[d + 2] || '')).trim(),
              summary: cells[d + 3] || '', ref_no: cells[d + 4] || '', country: cells[d + 5] || '', url });
          } else { fallback.push(clean('<x ' + chunk) + ' [' + url + ']'); }
        }
        if (fallback.length) out.push({ json: { kind: 'page', source: src.name, category: src.category, url: src.url, text: cut(fallback.join('\n'), cfg.maxPageChars), hashKey: '', hash: '' } });
        break;
      }
      default: { // 'html' – let Claude read the page
        let lines = htmlToLines(raw, src.url);
        if (src.prefilter) lines = keepRelevant(lines);
        const text = cut(lines.join('\n'), cfg.maxPageChars);
        if (text.length < 40) break;
        const hash = fnv(text);
        if (store.pageHashes[src.name] === hash) { out.push({ json: { kind: 'unchanged', source: src.name } }); break; }
        out.push({ json: { kind: 'page', source: src.name, category: src.category, url: src.url, text, hashKey: src.name, hash } });
      }
    }
  } catch (e) {
    out.push({ json: { kind: 'error', source: src.name, error: 'parse: ' + cut(e.message, 180) } });
  }
  if (out.length === before) out.push({ json: { kind: 'empty', source: src.name } });
}
return out;

